mapper.select:
SELECT CAST(r.id AS CHAR)
FROM acc_satisfaction_result r
JOIN acc_satisfaction_collection_task t ON t.id=r.collection_task_id AND t.tenant_id=r.tenant_id
WHERE r.tenant_id=#{query.tenantId} AND t.project_id=#{query.projectId}
  AND t.deleted=b'0'

  AND t.result_id=r.id AND r.result_status='EFFECTIVE' AND r.passed=b'1' AND r.effective_to IS NULL

AND r.id > #{query.afterId}


        AND 1=0
        AND t.id IN #{id}


ORDER BY r.id LIMIT #{query.limit}

SELECT r.id AS result_id, t.project_id, t.project_task_id, t.id AS collection_task_id, t.task_revision_no, r.questionnaire_id, r.response_id, r.result_version, r.version AS fact_version, r.score, r.threshold, r.passed, r.rule_version, r.result_status, r.archive_status, r.effective_from, r.effective_to FROM acc_satisfaction_result r JOIN acc_satisfaction_collection_task t ON t.tenant_id=r.tenant_id AND t.id=r.collection_task_id AND t.deleted=b'0' WHERE r.tenant_id=#{query.tenantId} AND t.project_id IN
#{projectId}
AND r.id=#{query.resultId}
ORDER BY r.create_time DESC, r.id DESC
